window.AUTH=window.AUTH||{};window.AUTH["09-1159"]={"d":"09-1159","id":"2010/09-1159","n":"Board of Trustees of the Leland Stanford Junior University v. Roche Molecular Systems, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"","url":"https://www.justice.gov/osg/media/197976/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/board-trs-leland-stanford-junior-univ-v-roche-moleclular-sys-inc-amicus-merits","n":44}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep563/usrep563776/usrep563776.pdf","tr":true,"items":[{"t":"case","label":"Arachnid, Inc. v. Merit Indus., Inc.","cite":"939 F.2d 1574","y":1991,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/939/1574/","op":1,"ar":1,"sum":"Describing inventor’s common-law and statutory rights.","sumSrc":"brief:0","by":{"0":"3"}},{"t":"case","label":"Board of Trs. of Leland Stanford Junior Univ. v. Roche Molecular Sys., Inc.","cite":"563 F. Supp. 2d 1016","y":2008,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/563/1016/","by":{"0":"11"}},{"t":"case","label":"Central Admixture Pharmacy Servs., Inc. v. Advanced Cardiac Solutions, P.C.","cite":"482 F.3d 1347","y":2007,"url":"https://www.courtlistener.com/c/F.3d/482/1347/","by":{"0":"20"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Echazabal","cite":"536 U.S. 73","y":2002,"id":"2001/00-1406","sc":1,"sum":"The Court held that the ADA did not preclude the EEOC's regulation allowing the harm-to-self defense. The Court reasoned that deference applied to the regulation because it made sense of the statutory defense for qualification standards that are job-related and consistent with business necessity.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Fenn v. Yale Univ.","cite":"393 F. Supp. 2d 133","y":2004,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/393/133/","ar":1,"by":{"0":"22"}},{"t":"case","label":"FilmTec Corp. v. Hydranautics","cite":"982 F.2d 1546","y":1992,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/982/1546/","op":6,"ar":3,"by":{"0":"3"}},{"t":"case","label":"Hall St. Assocs. v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"sum":"The Court affirmed the Ninth Circuit ruling and held that the provisions of the FAA are exclusive and cannot be expanded through contractual agreement. Writing for the majority, Justice David Souter pointed to words such as \"must\" and \"unless\" in the FAA as evidence that its provisions were intended to be mandatory and incapable of modification by the parties.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Heinemann v. United States","cite":"796 F.2d 451","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/796/451/","op":3,"ar":3,"sum":"Holding Executive Order constitutional and ﬁnding “no ‘taking’ because the invention was not the property of Heinemann”.","sumSrc":"opinion","by":{"0":"23"}},{"t":"case","label":"Platzer v. Sloan-Kettering Inst. for Cancer Research","cite":"787 F. Supp. 360","y":1992,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.%20Supp./787/360/","sum":"Concluding that “the intended beneficiaries of the Bayh-Dole Act are the [research] institutions themselves and the government,” not the inventors.","sumSrc":"brief:0","by":{"0":"17"}},{"t":"usc","label":"35 U.S.C. § 200","url":"https://www.law.cornell.edu/uscode/text/35/200","stext":{"head":"§200. Policy and objective","paras":[[0,"It is the policy and objective of the Congress to use the patent system to promote the utilization of inventions arising from federally supported research or development; to encourage maximum participation of small business firms in federally supported research and development efforts; to promote collaboration between commercial concerns and nonprofit organizations, including universities; to ensure that inventions made by nonprofit organizations and small business firms are used in a manner to promote free competition and enterprise without unduly encumbering future research and discovery; to promote the commercialization and public availability of inventions made in the United States by United States industry and labor; to ensure that the Government obtains sufficient rights in federally supported inventions to meet the needs of the Government and protect the public against nonuse or unreasonable use of inventions; and to minimize the costs of administering policies in this area."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/200?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§200. Policy and objective","tname":"Patents","by":{"0":"1, 2, 6"}},{"t":"usc","label":"35 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/35/201","subs":["(b)","(c)","(e)"],"stext":{"head":"§201. Definitions","paras":[[0,"As used in this chapter—"],[1,"(a) The term \"Federal agency\" means any executive agency as defined in section 105 of title 5, and the military departments as defined by section 102 of title 5."],[1,"(b) The term \"funding agreement\" means any contract, grant, or cooperative agreement entered into between any Federal agency, other than the Tennessee Valley Authority, and any contractor for the performance of experimental, developmental, or research work funded in whole or in part by the Federal Government. Such term includes any assignment, substitution of parties, or subcontract of any type entered into for the performance of experimental, developmental, or research work under a funding agreement as herein defined."],[1,"(c) The term \"contractor\" means any person, small business firm, or nonprofit organization that is a party to a funding agreement."],[1,"(d) The term \"invention\" means any invention or discovery which is or may be patentable or otherwise protectable under this title or any novel variety of plant which is or may be protectable under the Plant Variety Protection Act (7 U.S.C. 2321 et seq.)."],[1,"(e) The term \"subject invention\" means any invention of the contractor conceived or first actually reduced to practice in the performance of work under a funding agreement: Provided, That in the case of a variety of plant, the date of determination (as defined in section 41(d) 1 of the Plant Variety Protection Act (7 U.S.C. 2401(d))) must also occur during the period of contract performance."],[1,"(f) The term \"practical application\" means to manufacture in the case of a composition or product, to practice in the case of a process or method, or to operate in the case of a machine or system; and, in each case, under such conditions as to establish that the invention is being utilized and that its benefits are to the extent permitted by law or Government regulations available to the public on reasonable terms."],[1,"(g) The term \"made\" when used in relation to any invention means the conception or first actual reduction to practice of such invention."],[1,"(h) The term \"small business firm\" means a small business concern as defined at section 2 of Public Law 85–536 (15 U.S.C. 632) and implementing regulations of the Administrator of the Small Business Administration."],[1,"(i) The term \"nonprofit organization\" means universities and other institutions of higher education or an organization of the type described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)) and exempt from taxation under section 501(a) of the Internal Revenue Code (26 U.S.C. 501(a)) or any nonprofit scientific or educational organization qualified under a State nonprofit organization statute."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/201?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§201. Definitions","tname":"Patents","by":{"0":"6, 5, 5"}},{"t":"usc","label":"35 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/35/202","subs":["(a)","(a)(i)","(c)(1)","(c)(2)","(c)(3)","(c)(4)","(c)(6)","(c)(7)(A)","(c)(7)(B)","(c)(7)(C)","(d)"],"stext":{"head":"§202. Disposition of rights","paras":[[0,"(a) Each nonprofit organization or small business firm may, within a reasonable time after disclosure as required by paragraph (c)(1) of this section, elect to retain title to any subject invention: Provided, however, That a funding agreement may provide otherwise (i) when the contractor is not located in the United States or does not have a place of business located in the United States or is subject to the control of a foreign government, (ii) in exceptional circumstances when it is determined by the agency that restriction or elimination of the right to retain title to any subject invention will better promote the policy and objectives of this chapter (iii) when it is determined by a Government authority which is authorized by statute or Executive order to conduct foreign intelligence or counter-intelligence activities that the restriction or elimination of the right to retain title to any subject invention is necessary to protect the security of such activities or, (iv) when the funding agreement includes the operation of a Government-owned, contractor-operated facility of the Department of Energy primarily dedicated to that Department's naval nuclear propulsion or weapons related programs and all funding agreement limitations under this subparagraph on the contractor's right to elect title to a subject invention are limited to inventions occurring under the above two programs of the Department of Energy. The rights of the nonprofit organization or small business firm shall be subject to the provisions of paragraph (c) of this section and the other provisions of this chapter."],[0,"(b)(1) The rights of the Government under subsection (a) shall not be exercised by a Federal agency unless it first determines that at least one of the conditions identified in clauses (i) through (iv) of subsection (a) exists. Except in the case of subsection (a)(iii), the agency shall file with the Secretary of Commerce, within thirty days after the award of the applicable funding agreement, a copy of such determination. In the case of a determination under subsection (a)(ii), the statement shall include an analysis justifying the determination. In the case of determinations applicable to funding agreements with small business firms, copies shall also be sent to the Chief Counsel for Advocacy of the Small Business Administration. If the Secretary of Commerce believes that any individual determination or pattern of determinations is contrary to the policies and objectives of this chapter or otherwise not in conformance with this chapter, the Secretary shall so advise the head of the agency concerned and the Administrator of the Office of Federal Procurement Policy, and recommend corrective actions."],[0,"(2) Whenever the Administrator of the Office of Federal Procurement Policy has determined that one or more Federal agencies are utilizing the authority of clause (i) or (ii) of subsection (a) of this section in a manner that is contrary to the policies and objectives of this chapter, the Administrator is authorized to issue regulations describing classes of situations in which agencies may not exercise the authorities of those clauses."],[0,"(3) If the contractor believes that a determination is contrary to the policies and objectives of this chapter or constitutes an abuse of discretion by the agency, the determination shall be subject to section 203(b)."],[0,"(c) Each funding agreement with a small business firm or nonprofit organization shall contain appropriate provisions to effectuate the following:"],[1,"(1) That the contractor disclose each subject invention to the Federal agency within a reasonable time after it becomes known to contractor personnel responsible for the administration of patent matters, and that the Federal Government may receive title to any subject invention not disclosed to it within such time."],[1,"(2) That the contractor make a written election within two years after disclosure to the Federal agency (or such additional time as may be approved by the Federal agency) whether the contractor will retain title to a subject invention: Provided, That in any case where the 1-year period referred to in section 102(b) would end before the end of that 2-year period, the period for election may be shortened by the Federal agency to a date that is not more than sixty days before the end of that 1-year period: And provided further, That the Federal Government may receive title to any subject invention in which the contractor does not elect to retain rights or fails to elect rights within such times."],[1,"(3) That a contractor electing rights in a subject invention agrees to file a patent application prior to the expiration of the 1-year period referred to in section 102(b), and shall thereafter file corresponding patent applications in other countries in which it wishes to retain title within reasonable times, and that the Federal Government may receive title to any subject inventions in the United States or other countries in which the contractor has not filed patent applications on the subject invention within such times."],[1,"(4) With respect to any invention in which the contractor elects rights, the Federal agency shall have a nonexclusive, nontransferrable, irrevocable, paid-up license to practice or have practiced for or on behalf of the United States any subject invention throughout the world: Provided, That the funding agreement may provide for such additional rights, including the right to assign or have assigned foreign patent rights in the subject invention, as are determined by the agency as necessary for meeting the obligations of the United States under any treaty, international agreement, arrangement of cooperation, memorandum of understanding, or similar arrangement, including military agreement relating to weapons development and production."],[1,"(5) The right of the Federal agency to require periodic reporting on the utilization or efforts at obtaining utilization that are being made by the contractor or his licensees or assignees: Provided, That any such information as well as any information on utilization or efforts at obtaining utilization obtained as part of a proceeding under section 203 of this chapter shall be treated by the Federal agency as commercial and financial information obtained from a person and privileged and confidential and not subject to disclosure under section 552 of title 5."],[1,"(6) An obligation on the part of the contractor, in the event a United States patent application is filed by or on its behalf or by any assignee of the contractor, to include within the specification of such application and any patent issuing thereon, a statement specifying that the invention was made with Government support and that the Government has certain rights in the invention."],[1,"(7) In the case of a nonprofit organization, (A) a prohibition upon the assignment of rights to a subject invention in the United States without the approval of the Federal agency, except where such assignment is made to an organization which has as one of its primary functions the management of inventions (provided that such assignee shall be subject to the same provisions as the contractor); (B) a requirement that the contractor share royalties with the inventor; (C) except with respect to a funding agreement for the operation of a Government-owned-contractor-operated facility, a requirement that the balance of any royalties or income earned by the contractor with respect to subject inventions, after payment of expenses (including payments to inventors) incidental to the administration of subject inventions, be utilized for the support of scientific research or education; (D) a requirement that, except where it is determined to be infeasible following a reasonable inquiry, a preference in the licensing of subject inventions shall be given to small business firms; and (E) with respect to a funding agreement for the operation of a Government-owned-contractor-operated facility, requirements (i) that after payment of patenting costs, licensing costs, payments to inventors, and other expenses incidental to the administration of subject inventions, 100 percent of the balance of any royalties or income earned and retained by the contractor during any fiscal year up to an amount equal to 5 percent of the annual budget of the facility, shall be used by the contractor for scientific research, development, and education consistent with the research and development mission and objectives of the facility, including activities that increase the licensing potential of other inventions of the facility; provided that if said balance exceeds 5 percent of the annual budget of the facility, that 15 percent of such excess shall be paid to the Treasury of the United States and the remaining 85 percent shall be used for the same purposes described above in this clause; and (ii) that, to the extent it provides the most effective technology transfer, the licensing of subject inventions shall be administered by contractor employees on location at the facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/202?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§202. Disposition of rights","tname":"Patents","by":{"0":"6, 13, 15, 16, 18, 21, 6, 13, 15, 16, 18, 21, 7, 6, 18, 6, 16, 21, 13, 6, 18, 6, 18, 7, 16, 18, 32, 10, 6, 6, 16, 19, 6, 32, passim"}},{"t":"usc","label":"35 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/35/203","subs":["(a)"],"stext":{"head":"§203. March-in rights","paras":[[0,"(a) With respect to any subject invention in which a small business firm or nonprofit organization has acquired title under this chapter, the Federal agency under whose funding agreement the subject invention was made shall have the right, in accordance with such procedures as are provided in regulations promulgated hereunder to require the contractor, an assignee or exclusive licensee of a subject invention to grant a nonexclusive, partially exclusive, or exclusive license in any field of use to a responsible applicant or applicants, upon terms that are reasonable under the circumstances, and if the contractor, assignee, or exclusive licensee refuses such request, to grant such a license itself, if the Federal agency determines that such—"],[1,"(1) action is necessary because the contractor or assignee has not taken, or is not expected to take within a reasonable time, effective steps to achieve practical application of the subject invention in such field of use;"],[1,"(2) action is necessary to alleviate health or safety needs which are not reasonably satisfied by the contractor, assignee, or their licensees;"],[1,"(3) action is necessary to meet requirements for public use specified by Federal regulations and such requirements are not reasonably satisfied by the contractor, assignee, or licensees; or"],[1,"(4) action is necessary because the agreement required by section 204 has not been obtained or waived or because a licensee of the exclusive right to use or sell any subject invention in the United States is in breach of its agreement obtained pursuant to section 204."],[0,"(b) A determination pursuant to this section or section 202(b)(4) 1 shall not be subject to chapter 71 of title 41. An administrative appeals procedure shall be established by regulations promulgated in accordance with section 206. Additionally, any contractor, inventor, assignee, or exclusive licensee adversely affected by a determination under this section may, at any time within sixty days after the determination is issued, file a petition in the United States Court of Federal Claims, which shall have jurisdiction to determine the appeal on the record and to affirm, reverse, remand or modify, as appropriate, the determination of the Federal agency. In cases described in paragraphs (1) and (3) of subsection (a), the agency's determination shall be held in abeyance pending the exhaustion of appeals or petitions filed under the preceding sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/203?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§203. March-in rights","tname":"Patents","by":{"0":"21, 21"}},{"t":"usc","label":"35 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/35/204","by":{"0":"8, 21"}},{"t":"usc","label":"35 U.S.C. § 210","url":"https://www.law.cornell.edu/uscode/text/35/210","subs":["(a)"],"stext":{"head":"§210. Precedence of chapter","paras":[[0,"(a) This chapter shall take precedence over any other Act which would require a disposition of rights in subject inventions of small business firms or nonprofit organizations contractors in a manner that is inconsistent with this chapter, including but not necessarily limited to the following:"],[1,"(1) section 10(a) of the Act of June 29, 1935, as added by title I of the Act of August 14, 1946 (7 U.S.C. 427i(a); 60 Stat. 1085); 1"],[1,"(2) section 205(a) of the Act of August 14, 1946 (7 U.S.C. 1624(a); 60 Stat. 1090);"],[1,"(3) section 501(c) of the Federal Mine Safety and Health Act of 1977 (30 U.S.C. 951(c); 83 Stat. 742);"],[1,"(4) section 30168(e) 1 of title 49;"],[1,"(5) section 12 of the National Science Foundation Act of 1950 (42 U.S.C. 1871(a); 1 82 Stat. 360);"],[1,"(6) section 152 of the Atomic Energy Act of 1954 (42 U.S.C. 2182; 68 Stat. 943);"],[1,"(7) section 20135 of title 51;"],[1,"(8) section 6 of the Coal Research and Development Act of 1960 (30 U.S.C. 666; 74 Stat. 337);"],[1,"(9) section 4 of the Helium Act Amendments of 1960 (50 U.S.C. 167b; 74 Stat. 920);"],[1,"(10) section 32 of the Arms Control and Disarmament Act of 1961 (22 U.S.C. 2572; 75 Stat. 634);"],[1,"(11) section 9 of the Federal Nonnuclear Energy Research and Development Act of 1974 (42 U.S.C. 5908; 88 Stat. 1878);"],[1,"(12) section 5(d) of the Consumer Product Safety Act (15 U.S.C. 2054(d); 86 Stat. 1211);"],[1,"(13) section 3 of the Act of April 5, 1944 (30 U.S.C. 323; 58 Stat. 191); 1"],[1,"(14) section 8001(c)(3) of the Solid Waste Disposal Act (42 U.S.C. 6981(c); 90 Stat. 2829);"],[1,"(15) section 219 of the Foreign Assistance Act of 1961 (22 U.S.C. 2179; 83 Stat. 806);"],[1,"(16) section 427(b) of the Federal Mine Health and Safety Act of 1977 (30 U.S.C. 937(b); 86 Stat. 155);"],[1,"(17) section 306(d) of the Surface Mining and Reclamation Act of 1977 (30 U.S.C. 1226(d); 91 Stat. 455); 1"],[1,"(18) section 21(d) of the Federal Fire Prevention and Control Act of 1974 (15 U.S.C. 2218(d); 88 Stat. 1548);"],[1,"(19) section 6(b) of the Solar Photovoltaic Energy Research Development and Demonstration Act of 1978 (42 U.S.C. 5585(b); 92 Stat. 2516); 1"],[1,"(20) section 12 of the Native Latex Commercialization and Economic Development Act of 1978 (7 U.S.C. 178j; 92 Stat. 2533); and"],[1,"(21) section 408 of the Water Resources and Development Act of 1978 (42 U.S.C. 7879; 92 Stat. 1360)."],[0,"The Act creating this chapter shall be construed to take precedence over any future Act unless that Act specifically cites this Act and provides that it shall take precedence over this Act."],[0,"(b) Nothing in this chapter is intended to alter the effect of the laws cited in paragraph (a) of this section or any other laws with respect to the disposition of rights in inventions made in the performance of funding agreements with persons other than nonprofit organizations or small business firms."],[0,"(c) Nothing in this chapter is intended to limit the authority of agencies to agree to the disposition of rights in inventions made in the performance of work under funding agreements with persons other than nonprofit organizations or small business firms in accordance with the Statement of Government Patent Policy issued on February 18, 1983, agency regulations, or other applicable regulations or to otherwise limit the authority of agencies to allow such persons to retain ownership of inventions except that all funding agreements, including those with other than small business firms and nonprofit organizations, shall include the requirements established in section 202(c)(4) and section 203. Any disposition of rights in inventions made in accordance with the Statement or implementing regulations, including any disposition occurring before enactment of this section, are hereby authorized."],[0,"(d) Nothing in this chapter shall be construed to require the disclosure of intelligence sources or methods or to otherwise affect the authority granted to the Director of Central Intelligence by statute or Executive order for the protection of intelligence sources or methods."],[0,"(e) The provisions of the Stevenson-Wydler Technology Innovation Act of 1980 shall take precedence over the provisions of this chapter to the extent that they permit or require a disposition of rights in subject inventions which is inconsistent with this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/210?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§210. Precedence of chapter","tname":"Patents","by":{"0":"8, 21"}},{"t":"usc","label":"35 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/35/101","stext":{"head":"§101. Inventions patentable","paras":[[0,"Whoever invents or discovers any new and useful process, machine, manufacture, or composition of matter, or any new and useful improvement thereof, may obtain a patent therefor, subject to the conditions and requirements of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Inventions patentable","tname":"Patents","by":{"0":"21"}},{"t":"usc","label":"35 U.S.C. § 115","url":"https://www.law.cornell.edu/uscode/text/35/115","stext":{"head":"§115. Inventor's oath or declaration","paras":[[0,"(a) Naming the Inventor; Inventor's Oath or Declaration.—An application for patent that is filed under section 111(a) or commences the national stage under section 371 shall include, or be amended to include, the name of the inventor for any invention claimed in the application. Except as otherwise provided in this section, each individual who is the inventor or a joint inventor of a claimed invention in an application for patent shall execute an oath or declaration in connection with the application."],[0,"(b) Required Statements.—An oath or declaration under subsection (a) shall contain statements that—"],[1,"(1) the application was made or was authorized to be made by the affiant or declarant; and"],[1,"(2) such individual believes himself or herself to be the original inventor or an original joint inventor of a claimed invention in the application."],[0,"(c) Additional Requirements.—The Director may specify additional information relating to the inventor and the invention that is required to be included in an oath or declaration under subsection (a)."],[0,"(d) Substitute Statement.—"],[1,"(1) In general.—In lieu of executing an oath or declaration under subsection (a), the applicant for patent may provide a substitute statement under the circumstances described in paragraph (2) and such additional circumstances that the Director may specify by regulation."],[1,"(2) Permitted circumstances.—A substitute statement under paragraph (1) is permitted with respect to any individual who—"],[2,"(A) is unable to file the oath or declaration under subsection (a) because the individual—"],[3,"(i) is deceased;"],[3,"(ii) is under legal incapacity; or"],[3,"(iii) cannot be found or reached after diligent effort; or"],[2,"(B) is under an obligation to assign the invention but has refused to make the oath or declaration required under subsection (a)."],[1,"(3) Contents.—A substitute statement under this subsection shall—"],[2,"(A) identify the individual with respect to whom the statement applies;"],[2,"(B) set forth the circumstances representing the permitted basis for the filing of the substitute statement in lieu of the oath or declaration under subsection (a); and"],[2,"(C) contain any additional information, including any showing, required by the Director."],[0,"(e) Making Required Statements in Assignment of Record.—An individual who is under an obligation of assignment of an application for patent may include the required statements under subsections (b) and (c) in the assignment executed by the individual, in lieu of filing such statements separately."],[0,"(f) Time for Filing.—The applicant for patent shall provide each required oath or declaration under subsection (a), substitute statement under subsection (d), or recorded assignment meeting the requirements of subsection (e) no later than the date on which the issue fee for the patent is paid."],[0,"(g) Earlier-Filed Application Containing Required Statements or Substitute Statement.—"],[1,"(1) Exception.—The requirements under this section shall not apply to an individual with respect to an application for patent in which the individual is named as the inventor or a joint inventor and that claims the benefit under section 120, 121, 365(c), or 386(c) of the filing of an earlier-filed application, if—"],[2,"(A) an oath or declaration meeting the requirements of subsection (a) was executed by the individual and was filed in connection with the earlier-filed application;"],[2,"(B) a substitute statement meeting the requirements of subsection (d) was filed in connection with the earlier filed application with respect to the individual; or"],[2,"(C) an assignment meeting the requirements of subsection (e) was executed with respect to the earlier-filed application by the individual and was recorded in connection with the earlier-filed application."],[1,"(2) Copies of oaths, declarations, statements, or assignments.—Notwithstanding paragraph (1), the Director may require that a copy of the executed oath or declaration, the substitute statement, or the assignment filed in connection with the earlier-filed application be included in the later-filed application."],[0,"(h) Supplemental and Corrected Statements; Filing Additional Statements.—"],[1,"(1) In general.—Any person making a statement required under this section may withdraw, replace, or otherwise correct the statement at any time. If a change is made in the naming of the inventor requiring the filing of 1 or more additional statements under this section, the Director shall establish regulations under which such additional statements may be filed."],[1,"(2) Supplemental statements not required.—If an individual has executed an oath or declaration meeting the requirements of subsection (a) or an assignment meeting the requirements of subsection (e) with respect to an application for patent, the Director may not thereafter require that individual to make any additional oath, declaration, or other statement equivalent to those required by this section in connection with the application for patent or any patent issuing thereon."],[1,"(3) Savings clause.—A patent shall not be invalid or unenforceable based upon the failure to comply with a requirement under this section if the failure is remedied as provided under paragraph (1)."],[0,"(i) Acknowledgment of Penalties.—Any declaration or statement filed pursuant to this section shall contain an acknowledgment that any willful false statement made in such declaration or statement is punishable under section 1001 of title 18 by fine or imprisonment of not more than 5 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/115?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§115. Inventor's oath or declaration","tname":"Patents","by":{"0":"21"}},{"t":"usc","label":"35 U.S.C. § 116","url":"https://www.law.cornell.edu/uscode/text/35/116","by":{"0":"21"}},{"t":"usc","label":"35 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/35/152","stext":{"head":"§152. Issue of patent to assignee","paras":[[0,"Patents may be granted to the assignee of the inventor of record in the Patent and Trademark Office, upon the application made and the specification sworn to by the inventor, except as otherwise provided in this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/152?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§152. Issue of patent to assignee","tname":"Patents","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 1871","url":"https://www.law.cornell.edu/uscode/text/42/1871","subs":["(a)(1976)"],"by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 2182","url":"https://www.law.cornell.edu/uscode/text/42/2182","subs":["(1976)"],"stext":{"head":"§2182. Inventions conceived during Commission contracts; ownership; waiver; hearings","paras":[[0,"Any invention or discovery, useful in the production or utilization of special nuclear material or atomic energy, made or conceived in the course of or under any contract, subcontract, or arrangement entered into with or for the benefit of the Commission, regardless of whether the contract, subcontract, or arrangement involved the expenditure of funds by the Commission, shall be vested in, and be the property of, the Commission, except that the Commission may waive its claim to any such invention or discovery under such circumstances as the Commission may deem appropriate, consistent with the policy of this section. No patent for any invention or discovery, useful in the production or utilization of special nuclear material or atomic energy, shall be issued unless the applicant files with the application, or within thirty days after request therefor by the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office (unless the Commission advises the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office that its rights have been determined and that accordingly no statement is necessary) a statement under oath setting forth the full facts surrounding the making or conception of the invention or discovery described in the application and whether the invention or discovery was made or conceived in the course of or under any contract, subcontract, or arrangement entered into with or for the benefit of the Commission, regardless of whether the contract, subcontract, or arrangement involved the expenditure of funds by the Commission. The Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office shall as soon as the application is otherwise in condition for allowance forward copies of the application and the statement to the Commission."],[0,"The Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office may proceed with the application and issue the patent to the applicant (if the invention or discovery is otherwise patentable) unless the Commission, within 90 days after receipt of copies of the application and statement, directs the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office to issue the patent to the Commission (if the invention or discovery is otherwise patentable) to be held by the Commission as the agent of and on behalf of the United States."],[0,"If the Commission files such a direction with the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office, and if the applicant's statement claims, and the applicant still believes, that the invention or discovery was not made or conceived in the course of or under any contract, subcontract or arrangement entered into with or for the benefit of the Commission entitling the Commission to the title to the application or the patent the applicant may, within 30 days after notification of the filing of such a direction, request a hearing before the Patent Trial and Appeal Board. The Board shall have the power to hear and determine whether the Commission was entitled to the direction filed with the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office. The Board shall follow the rules and procedures established for interference and derivation cases and an appeal may be taken by either the applicant or the Commission from the final order of the Board to the United States Court of Appeals for the Federal Circuit in accordance with the procedures governing the appeals from the Patent Trial and Appeal Board."],[0,"If the statement filed by the applicant should thereafter be found to contain false material statements any notification by the Commission that it has no objections to the issuance of a patent to the applicant shall not be deemed in any respect to constitute a waiver of the provisions of this section or of any applicable civil or criminal statute, and the Commission may have the title to the patent transferred to the Commission on the records of the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office in accordance with the provisions of this section. A determination of rights by the Commission pursuant to a contractual provision or other arrangement prior to the request of the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office for the statement, shall be final in the absence of false material statements or nondisclosure of material facts by the applicant."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2182?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2182. Inventions conceived during Commission contracts; ownership; waiver; hearings","tname":"The Public Health and Welfare","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 2457","url":"https://www.law.cornell.edu/uscode/text/42/2457","subs":["(a)(1976)"],"stext":{"head":"§2457. Property rights in inventions","paras":[[0,"(a) Exclusive property of United States; issuance of patent"],[0,"Whenever any invention is made in the performance of any work under any contract of the Administration, and the Administrator determines that—"],[1,"(1) the person who made the invention was employed or assigned to perform research, development, or exploration work and the invention is related to the work he was employed or assigned to perform, or that it was within the scope of his employment duties, whether or not it was made during working hours, or with a contribution by the Government of the use of Government facilities, equipment, materials, allocated funds, information proprietary to the Government, or services of Government employees during working hours; or"],[1,"(2) the person who made the invention was not employed or assigned to perform research, development, or exploration work, but the invention is nevertheless related to the contract, or to the work or duties he was employed or assigned to perform, and was made during working hours, or with a contribution from the Government of the sort referred to in clause (1),"],[0,"such invention shall be the exclusive property of the United States, and if such invention is patentable a patent therefor shall be issued to the United States upon application made by the Administrator, unless the Administrator waives all or any part of the rights of the United States to such invention in conformity with the provisions of subsection (f) of this section."],[0,"(b) Contract provisions for furnishing reports of inventions, discoveries, improvements, or innovations"],[0,"Each contract entered into by the Administrator with any party for the performance of any work shall contain effective provisions under which such party shall furnish promptly to the Administrator a written report containing full and complete technical information concerning any invention, discovery, improvement, or innovation which may be made in the performance of any such work."],[0,"(c) Patent application"],[0,"No patent may be issued to any applicant other than the Administrator for any invention which appears to the Under Secretary of Commerce for Intellectual Property and Director of the United States Patent and Trademark Office (hereafter in this section referred to as the “Director”) to have significant utility in the conduct of aeronautical and space activities unless the applicant files with the Director, with the application or within thirty days after request therefor by the Director, a written statement executed under oath setting forth the full facts concerning the circumstances under which such invention was made and stating the relationship (if any) of such invention to the performance of any work under any contract of the Administration. Copies of each such statement and the application to which it relates shall be transmitted forthwith by the Director to the Administrator."],[0,"(d) Issuance of patent to applicant; request by Administrator; notice; hearing; determination; review"],[0,"Upon any application as to which any such statement has been transmitted to the Administrator, the Director may, if the invention is patentable, issue a patent to the applicant unless the Administrator, within ninety days after receipt of such application and statement, requests that such patent be issued to him on behalf of the United States. If, within such time, the Administrator files such a request with the Director, the Director shall transmit notice thereof to the applicant, and shall issue such patent to the Administrator unless the applicant within thirty days after receipt of such notice requests a hearing before the Board of Patent Appeals and Interferences on the question whether the Administrator is entitled under this section to receive such patent. The Board may hear and determine, in accordance with rules and procedures established for interference cases, the question so presented, and its determination shall be subject to appeal by the applicant or by the Administrator to the United States Court of Appeals for the Federal Circuit in accordance with procedures governing appeals from decisions of the Board of Patent Appeals and Interferences in other proceedings."],[0,"(e) False representations; request for transfer of title to patent; notice; hearing; determination; review"],[0,"Whenever any patent has been issued to any applicant in conformity with subsection (d) of this section, and the Administrator thereafter has reason to believe that the statement filed by the applicant in connection therewith contained any false representation of any material fact, the Administrator within five years after the date of issuance of such patent may file with the Director a request for the transfer to the Administrator of title to such patent on the records of the Director. Notice of any such request shall be transmitted by the Director to the owner of record of such patent, and title to such patent shall be so transferred to the Administrator unless within thirty days after receipt of such notice such owner of record requests a hearing before the Board of Patent Appeals and Interferences on the question whether any such false representation was contained in such statement. Such question shall be heard and determined, and determination thereof shall be subject to review, in the manner prescribed by subsection (d) of this section for questions arising thereunder. No request made by the Administrator under this subsection for the transfer of title to any patent, and no prosecution for the violation of any criminal statute, shall be barred by any failure of the Administrator to make a request under subsection (d) of this section for the issuance of such patent to him, or by any notice previously given by the Administrator stating that he had no objection to the issuance of such patent to the applicant therefor."],[0,"(f) Waiver of rights to inventions; Inventions and Contributions Board"],[0,"Under such regulations in conformity with this subsection as the Administrator shall prescribe, he may waive all or any part of the rights of the United States under this section with respect to any invention or class of inventions made or which may be made by any person or class of persons in the performance of any work required by any contract of the Administration if the Administrator determines that the interests of the United States will be served thereby. Any such waiver may be made upon such terms and under such conditions as the Administrator shall determine to be required for the protection of the interests of the United States. Each such waiver made with respect to any invention shall be subject to the reservation by the Administrator of an irrevocable, nonexclusive, nontransferable, royalty-free license for the practice of such invention throughout the world by or on behalf of the United States or any foreign government pursuant to any treaty or agreement with the United States. Each proposal for any waiver under this subsection shall be referred to an Inventions and Contributions Board which shall be established by the Administrator within the Administration. Such Board shall accord to each interested party an opportunity for hearing, and shall transmit to the Administrator its findings of fact with respect to such proposal and its recommendations for action to be taken with respect thereto."],[0,"(g) Repealed. Pub. L. 96–517, §7(b), Dec. 12, 1980, 94 Stat. 3027"],[0,"(h) Protection of title"],[0,"The Administrator is authorized to take all suitable and necessary steps to protect any invention or discovery to which he has title, and to require that contractors or persons who retain title to inventions or discoveries under this section protect the inventions or discoveries to which the Administration has or may acquire a license of use."],[0,"(i) Administration as defense agency"],[0,"The Administration shall be considered a defense agency of the United States for the purpose of chapter 17 of title 35."],[0,"(j) Definitions"],[0,"As used in this section—"],[1,"(1) the term “person” means any individual, partnership, corporation, association, institution, or other entity;"],[1,"(2) the term “contract” means any actual or proposed contract, agreement, understanding, or other arrangement, and includes any assignment, substitution of parties, or subcontract executed or entered into thereunder; and"],[1,"(3) the term “made”, when used in relation to any invention, means the conception or first actual reduction to practice of such invention."],[0,"(k) Objects intended for launch, launched, or assembled in outer space"],[0,"Any object intended for launch, launched, or assembled in outer space shall be considered a vehicle for the purpose of section 272 of title 35."],[0,"(l) Use or manufacture of patented inventions incorporated in space vehicles launched for persons other than United States"],[0,"The use or manufacture of any patented invention incorporated in a space vehicle launched by the United States Government for a person other than the United States shall not be considered to be a use or manufacture by or for the United States within the meaning of section 1498(a) of title 28, unless the Administration gives an express authorization or consent for such use or manufacture."]],"more":false,"ed":"2009","src":"https://www.govinfo.gov/link/uscode/42/2457?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2457. Property rights in inventions","tname":"The Public Health and Welfare","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 5908","url":"https://www.law.cornell.edu/uscode/text/42/5908","subs":["(a)(1976)"],"stext":{"head":"§5908. Patents and inventions","paras":[[0,"(a) Vesting of title to invention and issuance of patents to United States; prerequisites"],[0,"Whenever any invention is made or conceived in the course of or under any contract of the Department, other than nuclear energy research, development, and demonstration pursuant to the Atomic Energy Act of 1954 (42 U.S.C. 2011 et seq.) and the Secretary determines that—"],[1,"(1) the person who made the invention was employed or assigned to perform research, development, or demonstration work and the invention is related to the work he was employed or assigned to perform, or that it was within the scope of his employment duties, whether or not it was made during working hours, or with a contribution by the Government of the use of Government facilities, equipment, materials, allocated funds, information proprietary to the Government, or services of Government employees during working hours; or"],[1,"(2) the person who made the invention was not employed or assigned to perform research, development, or demonstration work, but the invention is nevertheless related to the contract or to the work or duties he was employed or assigned to perform, and was made during working hours, or with a contribution from the Government of the sort referred to in clause (1).1"],[0,"title to such invention shall vest in the United States, and if patents on such invention are issued they shall be issued to the United States, unless in particular circumstances the Secretary waives all or any part of the rights of the United States to such invention in conformity with the provisions of this section."],[0,"(b) Contract as requiring report to Department of invention, etc., made in course of contract"],[0,"Each contract entered into by the Department with any person shall contain effective provisions under which such person shall furnish promptly to the Department a written report containing full and complete technical information concerning any invention, discovery, improvement, or innovation which may be made in the course of or under such contract."],[0,"(c) Waiver by Secretary of rights of United States; regulations prescribing procedures; record of waiver determinations; objectives"],[0,"Under such regulations in conformity with the provisions of this section as the Secretary shall prescribe, the Secretary may waive all or any part of the rights of the United States under this section with respect to any invention or class of inventions made or which may be made by any person or class of persons in the course of or under any contract of the Department if he determines that the interests of the United States and the general public will be best served by such waiver. The Department shall maintain a publicly available, periodically updated record of waiver determinations. In making such determinations, the Secretary shall have the following objectives:"],[1,"(1) Making the benefits of the energy research, development, and demonstration program widely available to the public in the shortest practicable time."],[1,"(2) Promoting the commercial utilization of such inventions."],[1,"(3) Encouraging participation by private persons in the Department's energy research, development, and demonstration program."],[1,"(4) Fostering competition and preventing undue market concentration or the creation or maintenance of other situations inconsistent with the antitrust laws."],[0,"(d) Considerations applicable at time of contracting for waiver determination by Secretary"],[0,"In determining whether a waiver to the contractor at the time of contracting will best serve the interests of the United States and the general public, the Secretary shall specifically include as considerations—"],[1,"(1) the extent to which the participation of the contractor will expedite the attainment of the purposes of the program;"],[1,"(2) the extent to which a waiver of all or any part of such rights in any or all fields of technology is needed to secure the participation of the particular contractor;"],[1,"(3) the extent to which the contractor's commercial position may expedite utilization of the research, development, and demonstration program results;"],[1,"(4) the extent to which the Government has contributed to the field of technology to be funded under the contract;"],[1,"(5) the purpose and nature of the contract, including the intended use of the results developed thereunder;"],[1,"(6) the extent to which the contractor has made or will make substantial investment of financial resources or technology developed at the contractor's private expense which will directly benefit the work to be performed under the contract;"],[1,"(7) the extent to which the field of technology to be funded under the contract has been developed at the contractor's private expense;"],[1,"(8) the extent to which the Government intends to further develop to the point of commercial utilization the results of the contract effort;"],[1,"(9) the extent to which the contract objectives are concerned with the public health, public safety, or public welfare;"],[1,"(10) the likely effect of the waiver on competition and market concentration; and"],[1,"(11) in the case of a nonprofit educational institution, the extent to which such institution has a technology transfer capability and program, approved by the Secretary as being consistent with the applicable policies of this section."],[0,"(e) Considerations applicable to identified invention for waiver determination by Secretary"],[0,"In determining whether a waiver to the contractor or inventor or rights to an identified invention will best serve the interests of the United States and the general public, the Secretary shall specifically include as considerations paragraphs (4) through (11) of subsection (d) as applied to the invention and—"],[1,"(1) the extent to which such waiver is a reasonable and necessary incentive to call forth private risk capital for the development and commercialization of the invention; and"],[1,"(2) the extent to which the plans, intentions, and ability of the contractor or inventor will obtain expeditious commercialization of such invention."],[0,"(f) Rights subject to reservation where title to invention vested in United States"],[0,"Whenever title to an invention is vested in the United States, there may be reserved to the contractor or inventor—"],[1,"(1) a revocable or irrevocable nonexclusive, paid-up license for the practice of the invention throughout the world; and"],[1,"(2) the rights to such invention in any foreign country where the United States has elected not to secure patent rights and the contractor elects to do so, subject to the rights set forth in paragraphs (2), (3), (6), and (7) of subsection (h): Provided, That when specifically requested by the Department and three years after issuance of such a patent, the contractor shall submit the report specified in subsection (h)(1) of this section."],[0,"(g) to (i) Repealed. Pub. L. 96–517, §7(c), Dec. 12, 1980, 94 Stat. 3027"],[0,"(j) Small business status of applicant for waiver or licenses"],[0,"The Secretary shall, in granting waivers or licenses, consider the small business status of the applicant."],[0,"(k) Protection of invention, etc., rights by Secretary"],[0,"The Secretary is authorized to take all suitable and necessary steps to protect any invention or discovery to which the United States holds title, and to require that contractors or persons who acquire rights to inventions under this section protect such inventions."],[0,"(l) Department as defense agency of United States for purpose of maintaining secrecy of inventions"],[0,"The Department shall be considered a defense agency of the United States for the purpose of chapter 17 of title 35."],[0,"(m) Definitions"],[0,"As used in this section—"],[1,"(1) the term \"person\" means any individual, partnership, corporation, association, institution, or other entity;"],[1,"(2) the term \"contract\" means any contract, grant, agreement, understanding, or other arrangement, which includes research, development, or demonstration work, and includes any assignment, substitution of parties, or subcontract executed or entered into thereunder;"],[1,"(3) the term \"made\", when used in relation to any invention, means the conception or first actual reduction to practice of such invention;"],[1,"(4) the term \"invention\" means inventions or discoveries, whether patented or unpatented; and"],[1,"(5) the term \"contractor\" means any person having a contract with or on behalf of the Department."],[0,"(n) Report concerning applicability of existing patent policies to energy programs; time for submission to President and appropriate congressional committees"],[0,"Within twelve months after December 31, 1974, the Secretary with the participation of the Attorney General, the Secretary of Commerce, and other officials as the President may designate, shall submit to the President and the appropriate congressional committees a report concerning the applicability of existing patent policies affecting the programs under this chapter, along with his recommendations for amendments or additions to the statutory patent policy, including his recommendations on mandatory licensing, which he deems advisable for carrying out the purposes of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/5908?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§5908. Patents and inventions","tname":"The Public Health and Welfare","by":{"0":"3"}},{"t":"reg","label":"3 C.F.R. pt. 292","url":"https://www.ecfr.gov/current/title-3/part-292","by":{"0":"23"}},{"t":"reg","label":"3 C.F.R. pt. 355","url":"https://www.ecfr.gov/current/title-3/part-355","by":{"0":"23"}},{"t":"reg","label":"3 C.F.R. pt. 456","url":"https://www.ecfr.gov/current/title-3/part-456","by":{"0":"23"}},{"t":"reg","label":"3 C.F.R. pt. 220","url":"https://www.ecfr.gov/current/title-3/part-220","by":{"0":"28"}}]};